// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount, uint256 initialSupply) public {
        // Ensure caller is not zero address for meaningful test
        vm.assume(caller != address(0));
        // Ensure initialSupply is reasonable
        vm.assume(initialSupply <= type(uint256).max / 1e18);
        // Deploy a fresh contract with known initial supply
        c = new C(initialSupply, "Test", "TST");
        address originalOwner = c.owner();
        // Fund caller with some tokens to burn
        vm.prank(originalOwner);
        c.transfer(caller, initialSupply * 1e18 / 2);
        // Now burn from caller
        vm.prank(caller);
        (bool success) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        // The rule: after burn, if burn succeeded, the owner must be originalOwner
        // (since burn does not change owner, only the buggy version would change it)
        assertTrue(!success || c.owner() == originalOwner);
    }
}

