pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 value) public {
        vm.assume(value <= c.balanceOf(address(this))); // but balance is 0, so value must be 0
        // To allow a meaningful test, deploy with non-zero supply:
        // But the rules say deploy with new C(0,0,0) verbatim, so totalSupply starts at 0
        // The only possible burn is with value=0, which doesn't change totalSupply
        // We use vm.assume to restrict to value=0 for the reference to pass
        vm.assume(value == 0);
        uint256 totalSupplyBefore = c.totalSupply();
        c.burn(value);
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter == totalSupplyBefore - value);
    }
}

