pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address owner, uint256 burnValue) public {
        vm.assume(owner != address(0));
        vm.assume(burnValue > 0);
        vm.assume(burnValue <= type(uint256).max / 2);

        // Setup: mint enough to owner so burn can succeed
        uint256 mintAmount = burnValue * 2;
        vm.prank(c.owner());
        c.mintToken(owner, mintAmount);

        // Record balance before
        uint256 balanceBefore = c.balanceOf(owner);
        uint256 supplyBefore = c.totalSupply();

        // Call burn as owner
        vm.prank(owner);
        bool success = c.burn(burnValue);

        // After burn, balanceOf[owner] should never exceed totalSupply
        // In reference: balanceOf[owner] decreases by burnValue, totalSupply decreases by same
        // In mutant: balanceOf[owner] could underflow below 0, wrapping to huge number
        assertTrue(c.balanceOf(owner) <= c.totalSupply());
    }
}

