pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value, uint256 initialSupply) public {
        vm.assume(caller != address(0));
        vm.assume(initialSupply <= 1e20);
        c = new C(initialSupply, "T", "T");

        // Record sum of all balances before burn
        uint256 sumBefore = c.balanceOf(0);
        // In practice we cannot enumerate all addresses; we use a proxy: totalSupply should equal sum of balances
        // Instead, we measure delta: the owner's balance decrease and totalSupply decrease
        // The bug causes owner balance to underflow silently, so after burn, balanceOf[owner] may become huge
        // We check that totalSupply never exceeds the owner's balance (since only owner can burn)

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));

        // After burn, if the call succeeded (which it always does in M), the owner's balance should not be less than totalSupply
        // In P, the require prevents burn when balance < value, so balance >= totalSupply after
        // In M, balance can underflow, making balance huge
        uint256 ownerBalance = c.balanceOf(caller);
        uint256 totalSupply = c.totalSupply();
        assertTrue(ownerBalance >= totalSupply);
    }
}

