pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value, address[] memory others) public {
        vm.assume(caller != address(0));
        vm.assume(value > 0 && value <= type(uint256).max);
        for (uint i = 0; i < others.length; i++) {
            vm.assume(others[i] != address(0));
        }
        // Pre-state: mint some tokens to caller, then call burn
        uint256 initialBalance = 1000 ether;
        vm.prank(c.owner());
        c.mintToken(caller, initialBalance);
        vm.prank(c.owner());
        c.freezeAccount(caller, false);
        vm.prank(caller);
        c.burn(value);
        // Sum balances manually
        uint256 sum = c.balanceOf(caller);
        for (uint i = 0; i < others.length; i++) {
            sum += c.balanceOf(others[i]);
        }
        // Add owner's balance
        sum += c.balanceOf(c.owner());
        assertTrue(sum <= c.totalSupply());
    }
}

