pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        vm.assume(value <= 1000000);
        value = bound(value, 0, 1000000);

        // Mint some tokens to the contract owner first
        vm.prank(c.owner());
        c.mintToken(caller, 1000000);

        uint256 balanceBefore = c.balanceOf(caller);
        vm.assume(balanceBefore >= value);

        // Set caller as owner for the burn
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        if (!success) {
            assertTrue(true);
            return;
        }

        // After burn, sum of balances should equal totalSupply
        uint256 totalBalances = c.balanceOf(c.owner());
        uint256 totalSupplyAfter = c.totalSupply();
        // The reference ensures that totalBalances == totalSupplyAfter, but bug may break it
        assertTrue(totalBalances <= totalSupplyAfter);
    }
}

