pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burntAmount) public {
        vm.assume(caller != address(0));
        vm.assume(burntAmount <= type(uint256).max / 2);

        // Fund caller via mintToken (owner only) or direct balance manipulation
        // We'll use the owner to mint tokens to caller
        address owner = c.owner();
        vm.prank(caller);
        c.owned(); // This makes caller the owner

        // Mint tokens to caller
        c.mintToken(caller, burntAmount * 2);

        uint256 balanceBefore = c.balanceOf(caller);
        uint256 totalSupplyBefore = c.totalSupply();

        // Burn half of the balance
        uint256 burnValue = burntAmount;
        vm.assume(burnValue <= balanceBefore);

        c.burn(burnValue);

        uint256 balanceAfter = c.balanceOf(caller);
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule: balance decreases by exactly burnValue, totalSupply decreases by exactly burnValue
        assertTrue(balanceAfter == balanceBefore - burnValue && totalSupplyAfter == totalSupplyBefore - burnValue);
    }
}

