    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address randomAddr) public {
        // Restrict burnAmount to avoid overflow in totalSupply subtraction
        vm.assume(burnAmount <= type(uint256).max - 1e18);

        // Perform a mint to ensure totalSupply is positive and caller has balance
        uint256 mintAmount = 1e18;
        c.mintToken(address(this), mintAmount);

        // Get total supply before burn
        uint256 totalSupplyBefore = c.totalSupply();

        // Burn a portion
        if (burnAmount <= mintAmount) {
            c.burn(burnAmount);
        } else {
            // If burnAmount > mintAmount, expect revert, but still assert invariant for post-state
            vm.expectRevert();
            c.burn(burnAmount);
            // Note: after revert, state is unchanged, so balanceOf randomAddr <= totalSupply holds trivially
        }

        // General rule: no address's balance exceeds total supply
        // Since we cannot enumerate all addresses, we check a random one
        // This is a probabilistic invariant; for any specific address after any burn,
        // its balance must be <= totalSupply
        assertTrue(c.balanceOf(randomAddr) <= c.totalSupply());
    }
}

