pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol, uint256 burnValue) public {
        // Bound inputs to reasonable ranges
        vm.assume(initialSupply < 1e30);
        vm.assume(bytes(tokenName).length < 32);
        vm.assume(bytes(tokenSymbol).length < 32);
        burnValue = bound(burnValue, 0, 1e30);

        // Deploy contract with given parameters
        c = new C(initialSupply, tokenName, tokenSymbol);

        // Get initial owner balance and totalSupply (owner is c.owner())
        address owner = c.owner();
        uint256 initialOwnerBalance = c.balanceOf(owner);
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialSum = initialOwnerBalance + initialTotalSupply;

        // Ensure owner has enough balance for the burn
        vm.assume(burnValue <= initialOwnerBalance);

        // Execute burn via prank as owner
        vm.prank(owner);
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnValue));

        if (success) {
            uint256 finalOwnerBalance = c.balanceOf(owner);
            uint256 finalTotalSupply = c.totalSupply();
            uint256 finalSum = finalOwnerBalance + finalTotalSupply;
            // The sum should decrease by exactly burnValue in P; in M it decreases by burnValue + 1
            assertTrue(finalSum == initialSum - burnValue, "Sum did not match expected decrease");
        } else {
            // If it reverted, the invariant trivially holds (no state change)
            assertTrue(true, "Revert case");
        }
    }
}

